package org.eclipse.rdf4j.query.resultio.text.csv;

import static org.eclipse.rdf4j.rio.helpers.NTriplesUtil.BNODE_PATTERN;

import java.io.IOException;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Deque;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.Resource;
import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.impl.ListBindingSet;
import org.eclipse.rdf4j.query.resultio.text.SPARQLResultsXSVMappingStrategy;

import com.opencsv.CSVReader;
import com.opencsv.exceptions.CsvValidationException;

/**
 * Implements a {@link com.opencsv.bean.MappingStrategy} to allow opencsv to work in parallel. This is where the input
 * is converted into {@link org.eclipse.rdf4j.query.BindingSet}s.
 *
 * @author Andrew Rucker Jones
 */
public class SPARQLResultsCSVMappingStrategy extends SPARQLResultsXSVMappingStrategy {

	// CSV IRI is not wrapped in <>
	private static final String HEX = "[0-9A-Fa-f]";
	private static final String UCHAR = "(?:\\\\u" + HEX + "{4}|\\\\U" + HEX + "{8})";
	private static final String IRI_CSV = "(?:[^\u0000-\u0020<>\"{}|^`\\\\]|" + UCHAR + ")*";
	private static final Pattern IRI_CSV_PATTERN = Pattern.compile(IRI_CSV);
	private static final Pattern NUMBER_PATTER = Pattern.compile("^[-+]?[0-9]*\\.?[0-9]+([eE][-+]?[0-9]+)?");

	public SPARQLResultsCSVMappingStrategy(ValueFactory valueFactory) {
		super(valueFactory);
	}

	@Override
	public void captureHeader(CSVReader reader) throws IOException {
		try {
			bindingNames = Arrays.asList(reader.readNext());
		} catch (CsvValidationException ex) {
			throw new IOException(ex);
		}
	}

	@Override
	public BindingSet populateNewBean(String[] line) {
		List<Value> values = new ArrayList<>(line.length);
		for (String valueString : line) {
			Value v = null;
			if (valueString.startsWith("<<(")) {
				v = parseTripleTerm(valueString);
			} else if (valueString.startsWith("_:")) {
				v = valueFactory.createBNode(valueString.substring(2));
			} else if (!"".equals(valueString)) {
				if (numberPattern.matcher(valueString).matches()) {
					v = parseNumberPatternMatch(valueString);
				} else {
					try {
						v = valueFactory.createIRI(valueString);
					} catch (IllegalArgumentException e) {
						v = valueFactory.createLiteral(valueString);
					}
				}
			}
			values.add(v);
		}
		return new ListBindingSet(bindingNames, values.toArray(new Value[values.size()]));
	}

	Value parseTripleTerm(String valueString) {
		TripleTermParseState state = new TripleTermParseState(valueString);
		if (!state.startsWith("<<(")) {
			throw new IllegalArgumentException("Not a valid triple term: " + valueString);
		}
		Deque<TripleParseFrame> frames = new ArrayDeque<>();
		frames.push(new TripleParseFrame());
		state.advanceParser(3);
		while (!frames.isEmpty()) {
			state.skipWhiteSpaces();
			TripleParseFrame frame = frames.peek();
			if (frame.position == 3) {
				if (!state.startsWith(")>>")) {
					throw new IllegalArgumentException("Not a valid triple term: " + valueString);
				}
				state.advanceParser(3);
				Value completed = valueFactory.createTripleTerm(frame.subject, frame.predicate, frame.object);
				frames.pop();
				if (frames.isEmpty()) {
					if (!state.atEnd()) {
						throw new IllegalArgumentException("Not a valid triple term: " + valueString);
					}
					return completed;
				}
				frames.peek().accept(completed, valueString);
			} else if (state.startsWith("<<(")) {
				frames.push(new TripleParseFrame());
				state.advanceParser(3);
			} else {
				frame.accept(parseTripleComponent(state, valueString), valueString);
			}
		}
		throw new IllegalArgumentException("Not a valid triple term: " + valueString);
	}

	private Value parseTripleComponent(TripleTermParseState state, String original) {
		if (state.startsWith("_:")) {
			return parseBNode(state);
		}
		if (state.startsWith("\"")) {
			state.advanceParser(1);
			Value value = parseNumber(state);
			if (value == null) {
				value = tryToParseIRI(state);
			}
			if (value == null) {
				return parseLiteral(state);
			}
			if (!state.startsWith("\"")) {
				throw new IllegalArgumentException("Not a valid triple term: " + original);
			}
			state.advanceParser(1);
			return value;
		}
		return state.atEnd() ? null : tryToParseIRI(state);
	}

	private Value parseBNode(TripleTermParseState state) {
		Matcher bNodeMatcher = BNODE_PATTERN.matcher(state.source).region(state.parsedOffset, state.source.length());
		if (bNodeMatcher.lookingAt()) {
			String value = bNodeMatcher.group();
			Value v = valueFactory.createBNode(value.substring(2));
			state.parsedOffset = bNodeMatcher.end();
			return v;
		}
		return null;
	}

	private Value parseNumber(TripleTermParseState state) {
		Matcher numberMatcher = NUMBER_PATTER.matcher(state.source).region(state.parsedOffset, state.source.length());
		if (numberMatcher.lookingAt()) {
			String value = numberMatcher.group();
			state.parsedOffset = numberMatcher.end();
			return parseNumberPatternMatch(value);
		}
		return null;
	}

	private Value tryToParseIRI(TripleTermParseState state) {
		Value v = null;
		Matcher iriMatcher = IRI_CSV_PATTERN.matcher(state.source).region(state.parsedOffset, state.source.length());
		if (iriMatcher.lookingAt()) {
			String value = iriMatcher.group();
			try {
				v = valueFactory.createIRI(value);
				state.parsedOffset = iriMatcher.end();
			} catch (IllegalArgumentException e) {
				// Ignore error, we will try to parse to literal
			}
		}
		return v;
	}

	private Value parseLiteral(TripleTermParseState state) {
		int endOfLiteral = findEndOfLiteral(state.source, state.parsedOffset);
		if (endOfLiteral != -1) {
			String label = state.source.substring(state.parsedOffset, endOfLiteral - 1);
			// Unescape CSV quotes
			label = label.replace("\"\"", "\"");
			state.parsedOffset = endOfLiteral;
			return valueFactory.createLiteral(label);
		}
		return null;
	}

	private int findEndOfLiteral(String str, int start) {
		int i = start;

		while (i < str.length()) {
			char c = str.charAt(i);
			if (c == '"') {
				// Escaped quote ("")
				if (i + 1 < str.length() && str.charAt(i + 1) == '"') {
					i += 2;
				} else {
					// Position after closing quote
					return i + 1;
				}
			} else {
				i++;
			}
		}
		return -1; // No closing quote found
	}

	private static class TripleTermParseState {
		final String source;
		int parsedOffset;

		TripleTermParseState(String tripleStr) {
			source = tripleStr;
			parsedOffset = 0;
		}

		void advanceParser(int n) {
			parsedOffset += n;
		}

		boolean startsWith(String text) {
			return source.startsWith(text, parsedOffset);
		}

		boolean atEnd() {
			return parsedOffset == source.length();
		}

		void skipWhiteSpaces() {
			while (!atEnd() && Character.isWhitespace(source.charAt(parsedOffset))) {
				advanceParser(1);
			}
		}
	}

	private static final class TripleParseFrame {
		private Resource subject;
		private IRI predicate;
		private Value object;
		private int position;

		private void accept(Value value, String source) {
			if (position == 0 && value instanceof Resource resource) {
				subject = resource;
			} else if (position == 1 && value instanceof IRI iri) {
				predicate = iri;
			} else if (position == 2 && value != null) {
				object = value;
			} else {
				throw new IllegalArgumentException("Not a valid triple term: " + source);
			}
			position++;
		}
	}
}
